	@ParameterizedTest
	@ValueSource(strings = { "local", "mixed" })
	void correlatedIdentityPathsKeepSubstitutionThroughFederationContexts(String transport) throws Exception {
		initialize(transport);
		for (String path : List.of("<urn:absent>*", "<urn:absent>?", "(<urn:absent>*/<urn:absentTwo>*)")) {
			String body = "VALUES ?x { <urn:missing> } FILTER EXISTS { ?x " + path + " ?x }";
			assertThat(query("SELECT ?x WHERE { " + body + " }")).hasSize(1);
			assertThat(query("SELECT ?x WHERE { VALUES ?x { <urn:missing> } FILTER NOT EXISTS { ?x "
					+ path + " ?x } }")).isEmpty();
			assertThat(query("SELECT ?x WHERE { FILTER EXISTS { VALUES ?x { <urn:missing> } ?x "
					+ path + " ?x } }")).isEmpty();
			assertThat(query("SELECT ?x WHERE { FILTER EXISTS { VALUES ?x { <urn:missing> } "
					+ "FILTER EXISTS { GRAPH <urn:shared> { ?x " + path + " ?x } } } }")).hasSize(1);
		}
		// Sequence operands join independently. An unbound intermediate variable still needs a graph node,
		// even when each segment can match zero steps for a separately fixed endpoint.
		assertThat(query("SELECT ?x WHERE { VALUES ?x { <urn:missing> } FILTER EXISTS { "
				+ "?x (<urn:absent>?/<urn:absentTwo>?)+ ?x } }")).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(strings = { "local", "mixed", "sparql" })
	void fixedIdentityTermsSurviveNullableCompositePathRendering(String transport) throws Exception {
		initialize(transport);
		String path = "(<urn:absent>?/<urn:absentTwo>?)+";
		// Repetition does not turn an independent sequence's unbound intermediate into a syntactic term.
		assertThat(query("SELECT * WHERE { <urn:missing> " + path + " <urn:missing> }")).isEmpty();
		assertThat(query("SELECT ?y WHERE { <urn:missing> " + path + " ?y }")).isEmpty();
		assertThat(query("SELECT ?x WHERE { VALUES ?x { <urn:missing> } ?x " + path + " ?x }")).isEmpty();
		String sequence = "(<urn:absent>*/<urn:absentTwo>*)";
		assertThat(query("SELECT * WHERE { <urn:missing> " + sequence + " <urn:missing> }")).hasSize(1);
		assertThat(query("SELECT ?y WHERE { <urn:missing> " + sequence + " ?y }")).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(strings = { "join", "njoin", "nunion" })
	void preparedCompositionPreservesSubstitutionContext(String operator) throws Exception {
		initialize("local");
		var federationContext = federation.getFederationContext();
		var strategy = federationContext.createStrategy(null);
		var info = new QueryInfo(null, null, QueryType.SELECT, 0, false, federationContext, strategy, null);
		FedXZeroLengthPath path = new FedXZeroLengthPath(Scope.DEFAULT_CONTEXTS, Var.of("x"), Var.of("x"),
				null, info, List.of());
		TupleExpr expression = switch (operator) {
		case "join" -> new Join(new SingletonSet(), path);
		case "njoin" -> new NJoin(List.of(new SingletonSet(), path), info);
		default -> new NUnion(List.of(path, path.clone()), info);
		};
		QueryEvaluationContext base = new QueryEvaluationContext.Minimal(null, VF, null) {
			@Override
			public Set<String> getSubstitutionBindingNames() {
				return Set.of("x");
			}
		};
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("x", VF.createIRI("urn:missing"));
		try (var rows = strategy.precompile(expression, new DatasetQueryEvaluationContext(base, null))
				.evaluate(input)) {
			assertThat(QueryResults.asList(rows)).hasSize(operator.equals("nunion") ? 2 : 1);
		} finally {
			info.close();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "abort", "close" })
	void queryClosureCancelsAnInFlightSnapshot(String operation) throws Exception {
		initialize("wrapped-sparql");
		blockCapture = true;
		var context = federation.getFederationContext();
		var strategy = context.createStrategy(null);
		var info = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
		int initialConnections = closedConnections.get();
		try (var executor = Executors.newFixedThreadPool(2)) {
			var loading = executor.submit(() -> {
				try {
					strategy.prepareGraphSnapshots(endpoints, info);
					return (Throwable) null;
				} catch (Throwable failure) {
					return failure;
				}
			});
			assertThat(captureReady.await(30, TimeUnit.SECONDS)).isTrue();
			var closing = executor.submit(() -> {
				if (operation.equals("abort")) {
					info.abort();
				} else {
					info.close();
				}
			});
			try {
				closing.get(5, TimeUnit.SECONDS);
				assertThat(loading.get(5, TimeUnit.SECONDS)).isInstanceOf(QueryEvaluationException.class);
				assertThat(closedCaptureRows).hasValue(1);
				assertThat(closedConnections.get() - initialConnections).isEqualTo(2);
				assertThat(strategy.getGraphSnapshot(endpoints.getFirst())).isNull();
			} finally {
				captureResume.countDown();
				closing.get(5, TimeUnit.SECONDS);
				loading.get(5, TimeUnit.SECONDS);
				info.close();
			}
		}
	}

